import{_ as e,c as r,o as p,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"14、【大有】 乾下离上","description":"周易尚氏学 - 14、【大有】 乾下离上","frontmatter":{"title":"14、【大有】 乾下离上","description":"周易尚氏学 - 14、【大有】 乾下离上"},"headers":[],"relativePath":"zh/classics/shangshi/019.md","filePath":"zh/classics/shangshi/019.md"}'),h={name:"zh/classics/shangshi/019.md"};function s(t,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_14、【大有】-乾下离上" tabindex="-1">14、【大有】 乾下离上 <a class="header-anchor" href="#_14、【大有】-乾下离上" aria-label="Permalink to “14、【大有】 乾下离上”">​</a></h1><p>离乾皆居南。故曰大有。与同人义同也。元亨谓五也。五得尊位。故曰元。上下应故曰亨。坤五曰元吉。比五曰元永贞。损五益五鼎五。皆曰元吉。是其证。</p><p>彖曰。大有柔得尊位。大中而上下应之。曰大有。其德刚健而文明。应乎天而时行，是以元亨。</p><p>五天位二应之。故曰应乎天。离为夏。万物相见。故曰时行。</p><p>象曰。火在天上。大有。君子以遏恶扬善。顺天休命。</p><p>离为恶人。乾为善。二五相应予。而皆不当位。九二云。有攸往。是二必往五也。二往五是扬善也。二往五则五下居二。是遏恶也。乾为天为命。阴承乾。故曰顺天休命。休。美也。</p><p>初九。无交害。匪咎。艰则无咎。</p><p>初无应。阳遇阳失类。故无交。无交故无害。然须艰贞自守。方无咎也。</p><h3 id="象曰。大有初九。无交害也。" tabindex="-1">象曰。大有初九。无交害也。 <a class="header-anchor" href="#象曰。大有初九。无交害也。" aria-label="Permalink to “象曰。大有初九。无交害也。”">​</a></h3><p>九二。大车以载。有攸往。无咎。</p><p>伏坤为大车为载。按考工记。车人。大车。牛车也。两辕。牛在辕内。凡载物皆用大车。与马车回异。马车皆小车。一辕。两服在左右。专备人乘。若载物必大车也。故曰大车以载。上有应。往则得位。故无咎。</p><h3 id="象曰。大车以载。积中不败也。" tabindex="-1">象曰。大车以载。积中不败也。 <a class="header-anchor" href="#象曰。大车以载。积中不败也。" aria-label="Permalink to “象曰。大车以载。积中不败也。”">​</a></h3><p>二得中。承乘皆阳。皆曰积中。乾为实。故为积也。阳上升。故曰大车以载。义则本爻。象则用伏。(庐氏以乾为大车。乾似无此象。)</p><p>九三。公用亨于天子。小人弗克。</p><p>三为三公。兑为亨。天子谓五。小人谓四。四不中不正。失位无应。故曰小人。三兑体。可受亨于五。然而弗能者。以四亦阳害之也。</p><h3 id="象曰。公用亨于天子。小人害也。" tabindex="-1">象曰。公用亨于天子。小人害也。 <a class="header-anchor" href="#象曰。公用亨于天子。小人害也。" aria-label="Permalink to “象曰。公用亨于天子。小人害也。”">​</a></h3><p>九四。匪其彭。无咎。</p><p>释文云。彭。子夏传作旁。虞作尪。云作彭作旁。声字之误。王陶庐云。诸家易俱不作尪。此仲翔故生异说。与先儒为难。按说文云。彭。鼓声也。释名彭旁也。然则彭之旁。音义并同。诗鲁颂以车彭彭。毛传。有力有容也。齐风。行人彭彭。毛传多也。集韵云。强盛也。然则彭之义。为声容盛大无疑。兑为刚鲁。故曰彭。离为文。故曰匪。考工记。且其匪色。注。匪采貌也。少仪。车马之美。匪匪翼翼。注。行而有文也。匪其彭者。言文采之盛大显着也。</p><h3 id="象曰。匪其彭无咎。明辨皙也。" tabindex="-1">象曰。匪其彭无咎。明辨皙也。 <a class="header-anchor" href="#象曰。匪其彭无咎。明辨皙也。" aria-label="Permalink to “象曰。匪其彭无咎。明辨皙也。”">​</a></h3><p>明辨皙即释文盛之义。盖离为嘉会为礼。有礼则有文。上下秩然。明辨以哲。故无咎也。</p><p>六五。厥孚交如。威如。吉。</p><p>孚。信也。五阳全孚于五。故曰交如。离南面向明而治。故曰威如。</p><h3 id="象曰。厥孚交如。信以发志也。威如之吉。易而无备也。" tabindex="-1">象曰。厥孚交如。信以发志也。威如之吉。易而无备也。 <a class="header-anchor" href="#象曰。厥孚交如。信以发志也。威如之吉。易而无备也。" aria-label="Permalink to “象曰。厥孚交如。信以发志也。威如之吉。易而无备也。”">​</a></h3><p>五孚于诸阳。得行其志。孚即信。故曰信以发志。伏坎为信为志也。居尊位。人皆敬之。左右咸宜。故不必有所戒备。</p><p>上九。自天佑之。吉无不利。</p><p>五天位。佑助也。王弼云。余爻皆乘刚。上独履柔。故吉利也。</p><h3 id="象曰。大有上吉。自天佑也。" tabindex="-1">象曰。大有上吉。自天佑也。 <a class="header-anchor" href="#象曰。大有上吉。自天佑也。" aria-label="Permalink to “象曰。大有上吉。自天佑也。”">​</a></h3>',27)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
